export default async function install(app){const styles=[],observers=[],seen=new WeakSet(),panels=new Map();let stopped=false,queued=false;function style(root,text){const s=document.createElement('style');s.textContent=text;root.append(s);styles.push(s);}style(document.head,'.esri-popup .esri-features__heading.esri-widget__heading{text-align:center!important;}');function align(){for(const [root,entry] of panels){const header=root.querySelector('.header-container'),content=root.querySelector('.header--slotted-content');if(!header||!content)continue;const h=header.getBoundingClientRect(),c=content.getBoundingClientRect();if(h.width&&c.width){const offset=Math.max(0,(h.right-c.right)-(c.left-h.left));entry.style.textContent=`.header-container .header-content.header--slotted-content{padding-left:calc(12px + ${offset}px)!important;padding-right:12px!important;}`;}}}const resize=new ResizeObserver(align);function schedule(){if(queued||stopped)return;queued=true;queueMicrotask(()=>{queued=false;if(!stopped){scan();align();}});}function walk(root){if(!seen.has(root)){seen.add(root);const observer=new MutationObserver(records=>{if(records.some(rec=>[...rec.addedNodes].some(n=>n.nodeType===1&&n.localName!=='style')))schedule();});observer.observe(root,{childList:true,subtree:true});observers.push(observer);}if(root.host?.localName==='calcite-panel'&&!panels.has(root)){const s=document.createElement('style');root.append(s);styles.push(s);panels.set(root,{style:s});const header=root.querySelector('.header-container');if(header)resize.observe(header);const actions=root.querySelector('.header-actions--end');if(actions)resize.observe(actions);}for(const element of root.querySelectorAll('*'))if(element.shadowRoot)walk(element.shadowRoot);}function scan(){for(const popup of app.view.container.querySelectorAll('.esri-popup'))walk(popup);}const outer=new MutationObserver(schedule);outer.observe(app.view.container,{childList:true,subtree:true});observers.push(outer);app.onCleanup(()=>{stopped=true;resize.disconnect();observers.forEach(o=>o.disconnect());styles.forEach(s=>s.remove());});scan();align();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const title=app.view.container.querySelector('.esri-popup .esri-features__heading');const root=[...panels.keys()][0];const header=root?.querySelector('.header-container');if(!title||!header)return {installed:true,waitingForPopup:true};const t=title.getBoundingClientRect(),h=header.getBoundingClientRect();return {textAlign:getComputedStyle(title).textAlign,titleCenter:t.left+t.width/2,headerCenter:h.left+h.width/2,headerWidth:h.width};}